    v4Page({ path: '/portfolio/', page: 'work', active: 'Work', og: 'portfolio', priority: '0.9', title: `${COUNT.all} WordPress and WooCommerce projects, ${COUNT.live} live | Muhammad Adeel`, desc: `${COUNT.all} client sites built or fixed since 2023: fleet dealer, tour booking, telehealth, roofing, legal, finance. ${COUNT.live} live. Each with a short case study.`, body, schema: [crumbSchema([['Home', '/'], ['Work', '/portfolio/']])] });
